#!/bin/bash
# Runs inside the image build (see Containerfile). Everything here ends up in the OS image.
set -ouex pipefail

### 1. Theme files ---------------------------------------------------------------------
# Our own theme (generated by tools/generate_theme.py) + configs
cp -avf /ctx/system_files/. /
# GTK theme and cursors built from Chicago95 in the assets stage
cp -af /ctx/assets/. /
# readable by everyone (older asset builds left ImageMagick's 0600 files behind)
chmod -R go+rX /usr/share/themes/Classic7 /usr/share/icons/Chicago95_Standard_Cursors

glib-compile-schemas /usr/share/glib-2.0/schemas/

### 2. Make Classic 7 the system-wide default ---------------------------------------------
# Merge our defaults into /etc/xdg key by key, so Bazzite/Fedora settings we don't touch survive.
merge_ini() {
    local src="$1" dest="$2" group="" line key value
    mkdir -p "$(dirname "$dest")"
    touch "$dest"
    while IFS= read -r line || [[ -n "$line" ]]; do
        [[ -z "$line" || "$line" == \#* ]] && continue
        if [[ "$line" =~ ^\[(.*)\]$ ]]; then
            group="${BASH_REMATCH[1]}"
            continue
        fi
        key="${line%%=*}"
        value="${line#*=}"
        kwriteconfig6 --file "$dest" --group "$group" --key "$key" -- "$value"
    done < "$src"
}

for f in kdeglobals kwinrc dolphinrc mimeapps.list ksplashrc kservicemenurc; do
    merge_ini "/usr/share/classic7/xdg-defaults/$f" "/etc/xdg/$f"
done

# Lock screen: plain classic desktop blue instead of Bazzite's wallpaper (nested groups,
# so not via merge_ini)
for f in /etc/xdg/kscreenlockerrc ${KDE_PROFILE_DIR:-/usr/share/kde-settings/kde-profile/default/xdg}/kscreenlockerrc; do
    [[ -d "$(dirname "$f")" ]] || continue
    kwriteconfig6 --file "$f" --group Greeter --key WallpaperPlugin org.kde.color
    kwriteconfig6 --file "$f" --group Greeter --group Wallpaper --group org.kde.color --group General --key Color "58,110,165"
    # like Windows: the screen locks with Win+L, not by itself after idle time or after sleep
    kwriteconfig6 --file "$f" --group Daemon --key Autolock false
    kwriteconfig6 --file "$f" --group Daemon --key LockOnResume false
done

# Fedora's KDE profile also names a default Global Theme; point it at ours too
KDE_PROFILE=/usr/share/kde-settings/kde-profile/default/xdg
if [[ -d "$KDE_PROFILE" ]]; then
    merge_ini /usr/share/classic7/xdg-defaults/kdeglobals "$KDE_PROFILE/kdeglobals"
    merge_ini /usr/share/classic7/xdg-defaults/kwinrc "$KDE_PROFILE/kwinrc"
fi

### 3. Extra software ---------------------------------------------------------------------
# Bazzite already ships Steam, Lutris, GameMode, MangoHud and the AMD stack.
# LACT: fan curve / power limit / undervolt for the RX 7900 XTX.
if ! dnf5 -y install lact; then
    if dnf5 -y copr enable ilyaz/LACT; then
        dnf5 -y install lact || echo "WARNING: LACT not installed"
        dnf5 -y copr disable ilyaz/LACT
    fi
fi
if rpm -q lact; then
    systemctl enable lactd.service
fi

# Quick Launch widget for the taskbar lives in kdeplasma-addons
rpm -q kdeplasma-addons || dnf5 -y install kdeplasma-addons || echo "WARNING: no Quick Launch widget"

# Classic 7 Appearance dialog: Qt for Python (+ Pillow to recolour GTK button images)
dnf5 -y install python3-pyside6 python3-pillow
# The Aero and Basic looks draw Qt programs' buttons, tabs, scroll bars... with Kvantum
# (theme Classic7Aero in /usr/share/Kvantum); the Classic look keeps Qt's own Windows style
dnf5 -y install kvantum || echo "::warning title=Aero::Kvantum is not available: Qt programs keep the Windows style under Aero"
# Command Prompt: terminal emulation with pyte (Fedora package; pip as a fallback)
if ! dnf5 -y install python3-pyte; then
    dnf5 -y install python3-pip python3-wcwidth
    python3 -m pip install --no-cache-dir --prefix=/usr --no-deps pyte
fi
# Write (word processor): .docx via python-docx, old .doc via olefile (+ wv when available),
# spell checking via enchant/hunspell, and metric-compatible fonts for Calibri and Cambria
dnf5 -y install python3-docx python3-olefile || {
    dnf5 -y install python3-pip python3-lxml
    python3 -m pip install --no-cache-dir --prefix=/usr python-docx olefile
}
dnf5 -y install python3-enchant || echo "WARNING: no spell checking (python3-enchant)"
# Write opens PDFs as editable documents (PyMuPDF)
dnf5 -y install python3-pymupdf || python3 -m pip install --no-cache-dir --prefix=/usr pymupdf
# Mail: password store (KWallet via Secret Service) and HTML-to-text for the plain part
dnf5 -y install python3-keyring python3-secretstorage python3-html2text || echo "WARNING: Mail extras missing"
# 7-Zip (the 7z/7za/7zz commands) and Ark, its window ("7-Zip File Manager")
for pkg in 7zip ark; do rpm -q "$pkg" >/dev/null 2>&1 || dnf5 -y install "$pkg"; done
# Photo Viewer: more picture types (WebP/TIFF, HEIC/AVIF/JXL/RAW/PSD...), and folder browsing on
# network shares opened from Dolphin (kio-fuse gives programs a real path)
for pkg in qt6-qtimageformats kf6-kimageformats kio-fuse; do
    rpm -q "$pkg" >/dev/null 2>&1 || dnf5 -y install "$pkg" || echo "NOTE: $pkg not available"
done
# Disk Management: formatting (NTFS, exFAT, FAT32, ext4, Btrfs) and checking drives
for pkg in ntfs-3g ntfsprogs exfatprogs dosfstools btrfs-progs e2fsprogs util-linux; do
    rpm -q "$pkg" >/dev/null 2>&1 || dnf5 -y install "$pkg" || echo "NOTE: $pkg not available"
done
# Classic 7's small compiled parts (build_files/native), built here against this image's own KDE
# libraries: the taskbar's right-click menu (a Plasma plugin), the Properties plugin (opens the
# Windows 7 Properties window from Explorer and the desktop), classic7-grab (screen pictures for
# Quick Shot) and classic7-idle (idle time for the screensaver). The compilers and headers come in
# for this step only. Meanwhile every package already in the image is locked at its version, so the
# headers can't quietly update the desktop's own libraries (Fedora's archive of older updates has
# headers for an image that is a few updates behind).
rpm -qa --qf '%{NAME}.%{ARCH} %{EPOCHNUM}:%{VERSION}-%{RELEASE}\n' | LC_ALL=C sort > /tmp/rpms-before
# Remote Desktop: KRdp 6.7 with FreeRDP 3.32 lets nobody log in; its library is built again with
# KDE's fix (build_files/krdp/fix-krdp.sh says when that is needed and what it needs)
krdp_fix=0
bash /ctx/krdp/fix-krdp.sh check && krdp_fix=1
devel=()
# shellcheck disable=SC2046 # one name per word
for pkg in cmake gcc-c++ extra-cmake-modules libplasma-devel kf6-kcoreaddons-devel kf6-kconfig-devel \
           kf6-kpackage-devel kf6-kwindowsystem-devel kf6-kidletime-devel kf6-kio-devel qt6-qtbase-devel qt6-qtdeclarative-devel \
           $( ((krdp_fix)) && bash /ctx/krdp/fix-krdp.sh deps ); do
    rpm -q "$pkg" >/dev/null 2>&1 || devel+=("$pkg")
done
if ((${#devel[@]})); then
    archive=()
    dnf5 repo list --all 2>/dev/null | grep '^updates-archive ' >/dev/null && archive=(--enablerepo=updates-archive)
    vl=/etc/dnf/versionlock.toml
    [[ -f $vl ]] && cp -a $vl /tmp/versionlock.orig
    locked=0
    # shellcheck disable=SC2046 # one name per word
    dnf5 versionlock add $(rpm -qa --qf '%{NAME}\n' | LC_ALL=C sort -u) >/dev/null && locked=1
    if ! dnf5 -y install --setopt=install_weak_deps=False "${archive[@]}" "${devel[@]}"; then
        echo "NOTE: no headers match this image's library versions; taking the newest"
        rm -f $vl
        dnf5 -y install --setopt=install_weak_deps=False "${devel[@]}"
    fi
    if [[ -f /tmp/versionlock.orig ]]; then mv /tmp/versionlock.orig $vl; else rm -f $vl; fi
    echo "native parts: locked=$locked archive=${archive[*]}"
fi
cmake -S /ctx/native -B /tmp/native-build -DCMAKE_BUILD_TYPE=Release -DCMAKE_INSTALL_PREFIX=/usr \
    -DKDE_INSTALL_PLUGINDIR=lib64/qt6/plugins -DKDE_INSTALL_LIBEXECDIR=libexec -DBUILD_TESTING=OFF
cmake --build /tmp/native-build -j"$(nproc)"
cmake --install /tmp/native-build
rm -rf /tmp/native-build
if ((krdp_fix)); then
    TMPDIR=/var/tmp bash /ctx/krdp/fix-krdp.sh build \
        || echo "::warning title=Remote Desktop::KRdp's library could not be rebuilt with the FreeRDP 3.32 fix; logging in to this computer with Remote Desktop will fail"
fi
((${#devel[@]})) && dnf5 -y remove "${devel[@]}"
rpm -qa --qf '%{NAME}.%{ARCH} %{EPOCHNUM}:%{VERSION}-%{RELEASE}\n' | LC_ALL=C sort > /tmp/rpms-after
# packages whose version changed: their name is both among the lines that went and those that came
LC_ALL=C comm -23 /tmp/rpms-before /tmp/rpms-after | cut -d' ' -f1 | LC_ALL=C sort -u > /tmp/rpms-gone
LC_ALL=C comm -13 /tmp/rpms-before /tmp/rpms-after | cut -d' ' -f1 | LC_ALL=C sort -u > /tmp/rpms-came
updated=$(LC_ALL=C comm -12 /tmp/rpms-gone /tmp/rpms-came | tr '\n' ' ')
if [[ -n "$updated" ]]; then
    # the line shows on the build's summary page in GitHub
    echo "::warning title=Building the native parts updated image packages::$updated"
fi
left=$(LC_ALL=C comm -13 /tmp/rpms-gone /tmp/rpms-came | tr '\n' ' ')
[[ -n "$left" ]] && echo "NOTE: left from building the native parts: $left"
rm -f /tmp/rpms-before /tmp/rpms-after /tmp/rpms-gone /tmp/rpms-came
test -f /usr/lib64/qt6/plugins/plasma/containmentactions/org.classic7.taskbarmenu.so
test -f /usr/lib64/qt6/plugins/kf6/propertiesdialog/classic7_properties.so
test -x /usr/libexec/classic7-grab
test -x /usr/libexec/classic7-idle
test -f /usr/share/applications/classic7-grab.desktop
# Sheet (spreadsheets): .xlsx through openpyxl, old .xls through xlrd
for pkg in python3-openpyxl python3-xlrd; do
    rpm -q "$pkg" >/dev/null 2>&1 || dnf5 -y install "$pkg" || echo "NOTE: $pkg not available"
done
for pkg in hunspell-da hunspell-en hunspell-en-US hunspell-en-GB google-carlito-fonts \
           google-crosextra-caladea-fonts google-caladea-fonts wv; do
    rpm -q "$pkg" >/dev/null 2>&1 || dnf5 -y install "$pkg" || echo "NOTE: $pkg not available"
done
chmod 0755 /usr/bin/classic7-write /usr/bin/classic7-mail /usr/bin/classic7-network /usr/bin/classic7-netdrive /usr/libexec/classic7-update-system /usr/libexec/classic7-netdrive-helper \
    /usr/bin/classic7-taskbar-pin /usr/libexec/classic7-tray-fix /usr/bin/classic7-photos /usr/bin/classic7-show \
    /usr/bin/classic7-diskmgmt /usr/libexec/classic7-disk-helper /usr/bin/classic7-control \
    /usr/bin/classic7-taskmgr /usr/bin/classic7-security /usr/bin/classic7-jumplist \
    /usr/bin/classic7-system /usr/bin/classic7-devmgmt /usr/bin/classic7-sheet /usr/bin/classic7-arrange \
    /usr/bin/classic7-programs /usr/bin/classic7-notepad /usr/bin/classic7-calc /usr/bin/classic7-charmap \
    /usr/bin/classic7-stickynotes /usr/bin/classic7-quickshot /usr/bin/classic7-paint \
    /usr/bin/classic7-recyclebin /usr/bin/classic7-properties /usr/libexec/classic7-sessiond \
    /usr/bin/classic7-timedate /usr/bin/classic7-mixer /usr/bin/classic7-actioncenter \
    /usr/bin/classic7-msconfig /usr/bin/classic7-eventvwr /usr/bin/classic7-resmon /usr/bin/classic7-firewall \
    /usr/libexec/classic7-firewall-helper /usr/bin/classic7-screensaver /usr/bin/classic7-goodbye /usr/bin/classic7-mstsc \
    /usr/bin/classic7-taskbar-properties
# KWin looks for window switchers and scripts in kwin-wayland/ (Plasma 6.4+) and, for older
# packages, in kwin/: make ours visible in both
for d in tabbox/classic7 tabbox/classic7aero scripts/classic7-aeroshake; do
    mkdir -p "/usr/share/kwin/$(dirname "$d")"
    [[ -e "/usr/share/kwin/$d" ]] || ln -s "../../kwin-wayland/$d" "/usr/share/kwin/$d"
done
# one network icon in the tray: fixes the saved panel layout at login, before Plasma starts
systemctl --global enable classic7-tray-fix.service
# file copy progress windows and the Recycle Bin icon; starts before the desktop (see the unit)
systemctl --global enable classic7-sessiond.service
# Classic 7 Update: which build this is (the updater compares it at login to bring each
# account's settings up to date after a new version starts)
base="$(. /usr/lib/os-release; echo "${VERSION_ID:-}${OSTREE_VERSION:+ ($OSTREE_VERSION)}")"
content="$(cd /ctx/system_files && find . -type f -print0 | LC_ALL=C sort -z | xargs -0 sha256sum | sha256sum | cut -c1-16)"
printf '{"build": "%s", "base": "%s", "content": "%s"}\n' "$(date -u +%Y-%m-%dT%H:%MZ)" \
    "$base" "$content" > /usr/share/classic7/build-info.json
chmod 0755 /usr/bin/classic7-appearance /usr/bin/classic7-computer /usr/bin/classic7-prompt /usr/bin/classic7-run /usr/bin/classic7-sendto /usr/bin/classic7-update /usr/libexec/classic7-first-login
python3 -c "import PySide6.QtSvg, PySide6.QtWidgets, PySide6.QtPrintSupport, PIL, pyte, docx, olefile"
PYTHONPATH=/usr/lib/classic7 python3 -c "import classic7theme, classic7aero, classic7kvantum, classic7appearance, drives, prompt_safety, prompt_recipes, prompt_llm, prompt_term, prompt_gui, write_model, write_page, write_ribbon, write_docx, write_rtf, write_doc, write_pdf, write_app, update_core, update_gui, netconf, netconn_gui, netdrive, netdrive_gui, mail_accounts, mail_oauth, mail_store, mail_imap, mail_send, mail_render, mail_worker, mail_icons, mail_ui, mail_view, mail_contacts, mail_setup, mail_compose, mail_gui, photos_core, photos_icons, photos_app, show_model, show_designs, show_geom, show_text, show_render, show_pptx, show_ppt, show_edit, show_widgets, show_dialogs, show_slideshow, show_chart, show_app, disks, diskmgmt_app, control_items, control_panel, session_actions, kwin_bridge, taskmgr_data, taskmgr_app, security_screen, sysinfo, system_app, devmgmt_app, sheet_ref, sheet_formula, sheet_numfmt, sheet_model, sheet_chart, sheet_io, sheet_ops, sheet_grid, sheet_dialogs, sheet_print, sheet_app, programs_data, programs_app, accessories, notepad_app, calc_engine, calc_app, charmap_app, stickynotes_app, quickshot_app, paint_canvas, paint_app, recyclebin_app, properties_app, sessiond, timedate_app, mixer_app, actioncenter_checks, actioncenter_app, cpl_page, msconfig_app, eventvwr_app, resmon_app, firewall_app, screensaver_app, remote_app, remote_server, taskbar_props, taskbar_props_app"
python3 -c "import PySide6.QtWebEngineWidgets, keyring, html2text" || echo "WARNING: Mail falls back to the simple message view"
/usr/bin/classic7-prompt --tasks update >/dev/null
# The Computer window mounts and ejects through UDisks
command -v udisksctl
python3 -m compileall -q /usr/lib/classic7

### 4. Sanity checks: fail the build early if a theme part is missing -------------------
test -f /usr/share/plasma/look-and-feel/org.classic7.desktop/metadata.json
test -f /usr/share/plasma/desktoptheme/classic7/metadata.json
test -f /usr/share/aurorae/themes/Classic7/decoration.svg
test -f /usr/share/color-schemes/Classic7.colors
test -f /usr/share/themes/Classic7/gtk-3.0/gtk.css
[[ -z "$(find /usr/share/themes/Classic7 /usr/share/icons/Chicago95_Standard_Cursors ! -perm -o+r -print -quit)" ]]
test -f /usr/share/icons/breeze/index.theme
test -d /usr/share/icons/Chicago95_Standard_Cursors/cursors
grep -q '^LookAndFeelPackage=org.classic7.desktop' /etc/xdg/kdeglobals
# Aero and Basic; new accounts start in Aero (/etc/skel), older ones keep Classic
for f in /usr/share/plasma/look-and-feel/org.classic7.aero.desktop/metadata.json \
         /usr/share/plasma/look-and-feel/org.classic7.aero.desktop/contents/layouts/org.kde.plasma.desktop-layout.js \
         /usr/share/plasma/desktoptheme/classic7-aero/metadata.json \
         /usr/share/plasma/desktoptheme/classic7-aero/translucent/widgets/panel-background.svg \
         /usr/share/plasma/desktoptheme/classic7-basic/metadata.json \
         /usr/share/aurorae/themes/Classic7Aero/decoration.svg /usr/share/aurorae/themes/Classic7Basic/decoration.svg \
         /usr/share/aurorae/themes/Classic7Aero/glow.svg \
         /usr/share/kwin/decorations/classic7aero/contents/ui/main.qml \
         /usr/share/kwin/decorations/classic7aero/contents/ui/CaptionButton.qml \
         /usr/share/kwin/decorations/classic7basic/contents/ui/main.qml \
         /usr/share/kwin/decorations/classic7basic/metadata.json \
         /usr/share/color-schemes/Classic7Aero.colors /usr/share/classic7/start-orb.svg \
         /usr/share/classic7/start-orb-hover.svg /usr/share/classic7/start-orb-pressed.svg \
         /usr/share/Kvantum/Classic7Aero/Classic7Aero.kvconfig /usr/share/Kvantum/Classic7Aero/Classic7Aero.svg \
         /usr/share/themes/Classic7Aero/gtk-3.0/gtk.css /usr/share/themes/Classic7Aero/gtk-4.0/gtk.css \
         /usr/share/wallpapers/Classic7Aero/metadata.json /usr/share/wallpapers/Classic7Aero/contents/images/1920x1080.jpg \
         /usr/share/kwin-wayland/tabbox/classic7aero/contents/ui/main.qml /etc/xdg/Kvantum/kvantum.kvconfig \
         /etc/skel/.config/classic7/appearance.json /etc/skel/.config/kdeglobals /etc/skel/.config/kwinrc \
         /etc/skel/.config/plasmarc /etc/skel/.config/kcminputrc /etc/skel/.config/Kvantum/kvantum.kvconfig; do
    test -f "$f" || { echo "missing: $f" >&2; exit 1; }
done
grep -q '"look": "aero"' /etc/skel/.config/classic7/appearance.json
grep -q '^LookAndFeelPackage=org.classic7.aero.desktop' /etc/skel/.config/kdeglobals
# the window borders are QML decorations that show the Aurorae themes' pictures
grep -q '^theme=classic7aero$' /etc/skel/.config/kwinrc
grep -q 'svgDir: "/usr/share/aurorae/themes/Classic7Aero"' /usr/share/kwin/decorations/classic7aero/contents/ui/main.qml
[[ -z "$(find /usr/share/themes/Classic7Aero /usr/share/Kvantum/Classic7Aero /usr/share/wallpapers/Classic7Aero \
            ! -perm -o+r -print -quit)" ]]
# Windows 7's white cursors: Breeze Light (Plasma's breeze package), else Breeze
if [[ ! -d /usr/share/icons/Breeze_Light/cursors ]]; then
    echo "::warning title=Aero::no Breeze_Light cursors: new accounts get breeze_cursors"
    sed -i 's/Breeze_Light/breeze_cursors/' /etc/skel/.config/kcminputrc \
        /etc/skel/.config/gtk-3.0/settings.ini /etc/skel/.config/gtk-4.0/settings.ini
fi
# Kvantum draws Qt programs' controls in Aero and Basic; without it new accounts get Fusion
if ! ls /usr/lib*/qt6/plugins/styles/libkvantum.so >/dev/null 2>&1; then
    sed -i 's/^widgetStyle=kvantum$/widgetStyle=Fusion/' /etc/skel/.config/kdeglobals
fi
# Explorer layout for new accounts
test -f /etc/skel/.local/state/dolphinstaterc
test -f /etc/skel/.local/share/kxmlgui5/dolphin/dolphinui.rc
grep -q '^ShowStatusBar=FullWidth' /etc/xdg/dolphinrc
# Computer window, desktop icons, Win+E
test -x /usr/bin/classic7-computer
test -f /usr/share/applications/classic7-computer.desktop
test -f /usr/share/classic7/desktop/computer.desktop
test -f /etc/xdg/autostart/classic7-first-login.desktop
test -f /etc/skel/.config/kglobalshortcutsrc
# Right-click menus
test -x /usr/bin/classic7-sendto
test -x /usr/bin/classic7-update
test -f /usr/share/kio/servicemenus/classic7-sendto.desktop
test -f /usr/share/kio/servicemenus/classic7-createshortcut.desktop
grep -q '^ShowOpenInNewTab=false' /etc/xdg/dolphinrc
# Command Prompt
test -x /usr/bin/classic7-prompt
test -f /usr/share/applications/classic7-prompt.desktop
grep -q '^TerminalApplication=classic7-prompt' /etc/xdg/kdeglobals
grep -q '^WallpaperPlugin=org.kde.color' /etc/xdg/kscreenlockerrc
grep -q '^Autolock=false' /etc/xdg/kscreenlockerrc
test -f /usr/share/polkit-1/rules.d/50-classic7.rules
# Start menu
test -f /usr/share/plasma/plasmoids/org.classic7.startmenu/metadata.json
test -f /usr/share/plasma/plasmoids/org.classic7.startmenu/contents/ui/main.qml
test -f /usr/share/classic7/start-button-pressed.svg
test -f /usr/share/applications/classic7-run.desktop
test -x /usr/bin/classic7-run
# Write
test -x /usr/bin/classic7-write
test -f /usr/share/applications/classic7-write.desktop
grep -q "^application/msword=classic7-write.desktop" /etc/xdg/mimeapps.list
test -f /usr/share/kio/servicemenus/classic7-write-pdf.desktop
test -f /usr/share/kio/servicemenus/classic7-taskbar-pin.desktop
/usr/bin/classic7-taskbar-pin --help >/dev/null
test -L /etc/systemd/user/plasma-core.target.wants/classic7-tray-fix.service
test -L /etc/systemd/user/plasma-core.target.wants/classic7-sessiond.service
PYTHONPATH=/usr/lib/classic7 python3 -c "import write_pdf"
# Mail
test -x /usr/bin/classic7-mail
test -f /usr/share/applications/classic7-mail.desktop
grep -q "^x-scheme-handler/mailto=classic7-mail.desktop" /etc/xdg/mimeapps.list
# Show (presentations)
test -x /usr/bin/classic7-show
test -f /usr/share/applications/classic7-show.desktop
test -f /usr/share/kio/servicemenus/classic7-show-play.desktop
grep -q "^application/vnd.openxmlformats-officedocument.presentationml.presentation=classic7-show.desktop" /etc/xdg/mimeapps.list
grep -q "^application/vnd.ms-powerpoint=classic7-show.desktop" /etc/xdg/mimeapps.list
python3 -c "import lxml.etree, olefile"
PYTHONPATH=/usr/lib/classic7 QT_QPA_PLATFORM=offscreen python3 -c "
import show_model, show_pptx, show_render
from PySide6.QtWidgets import QApplication; app = QApplication([])
p = show_model.new_presentation('horizon'); show_pptx.write_pptx(p, '/tmp/c7show.pptx')
q = show_pptx.read_pptx('/tmp/c7show.pptx'); assert len(q.slides) == 1
img = show_render.Renderer(q).thumbnail(q.slides[0], 200); assert not img.isNull()"
rm -f /tmp/c7show.pptx
# Accessories: Notepad, Calculator, Character Map, Sticky Notes, Quick Shot, Paint
for a in notepad calc charmap stickynotes quickshot paint; do
    test -x /usr/bin/classic7-$a
    test -f /usr/share/applications/classic7-$a.desktop
done
test -f /etc/xdg/autostart/classic7-quickshot.desktop
grep -q "^text/plain=classic7-notepad.desktop" /etc/xdg/mimeapps.list
PYTHONPATH=/usr/lib/classic7 python3 -c "
from calc_engine import Engine
e = Engine(); [e.digit(c) for c in '12']; e.binary('+'); e.digit('3'); e.binary('*'); e.digit('4'); e.equals()
assert e.display() == '60', e.display()"
# Programs and Features, the taskbar menu
test -x /usr/bin/classic7-programs
/usr/bin/classic7-programs --help >/dev/null
